        "factor": "Executive negotiations on Taiwan tax framework",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Negotiations on a comprehensive tax framework could provide a pathway for implementing legislation once an agreement is in place."
      },
      {
        "factor": "Overall federal enactment rate / political climate",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Historical data show a low enactment rate for introduced bills, and the current Congress has been particularly gridlocked; this weighs on probabilities."
      },
      {
        "factor": "Election year dynamics",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Election-year dynamics generally depress legislative output and prioritization, reducing chances of new enactments before May 2026."
      }
